    74→}
    75→
    76→interface QuestionDragItem {
    77→	type: "question";
    78→	id: string;
    79→}
    80→
    81→type DragItem = PaletteDragItem | QuestionDragItem;
    82→
    83→interface SurveyBuilderProps {
    84→	survey: Survey;
    85→	questions: Question[];
    86→	className?: string;
    87→}
    88→
    89→export function SurveyBuilder({
    90→	survey,
    91→	questions: initialQuestions,
    92→	className,
    93→}: SurveyBuilderProps) {
    94→	const [selectedQuestionId, setSelectedQuestionId] = useState<string | null>(
    95→		null,
    96→	);
    97→	const [activeTab, setActiveTab] = useState<"build" | "preview">("build");
    98→	const [questions, setQuestions] = useState(initialQuestions);
    99→	const [activeDragItem, setActiveDragItem] = useState<DragItem | null>(null);
   100→	const [overId, setOverId] = useState<string | null>(null);
   101→	const [paletteOpen, setPaletteOpen] = useState(false);
   102→	const [propertiesOpen, setPropertiesOpen] = useState(false);
   103→	const [dropped, setDropped] = useState(false);
   104→
   105→	// Responsive breakpoints
   106→	const isDesktop = useMediaQuery("(min-width: 1024px)");
   107→
   108→	const queryClient = useQueryClient();
   109→
   110→	// Sync state when initialQuestions changes
   111→	useEffect(() => {
   112→		setQuestions(initialQuestions);
   113→	}, [initialQuestions]);
   114→
   115→	// Reset dropped state after animation completes
   116→	useEffect(() => {
   117→		if (dropped) {
   118→			const timer = setTimeout(() => {
   119→				setDropped(false);
   120→			}, 500);
   121→			return () => clearTimeout(timer);
   122→		}
   123→	}, [dropped]);
   124→
   125→	// Reorder mutation
   126→	const reorderMutation = useMutation(
   127→		orpc.question.reorder.mutationOptions({
   128→			onSuccess: () => {
   129→				queryClient.invalidateQueries({ queryKey: ["question"] });
   130→			},
   131→			onError: (error) => {
   132→				toast.error(error.message || "Failed to reorder questions");
   133→			},
   134→		}),
   135→	);
   136→
   137→	// DnD sensors
   138→	const sensors = useSensors(
   139→		useSensor(PointerSensor, {
   140→			activationConstraint: {
   141→				distance: 5,
   142→			},
   143→		}),
   144→		useSensor(KeyboardSensor, {
   145→			coordinateGetter: sortableKeyboardCoordinates,
   146→		}),
   147→	);
   148→
   149→	// Custom collision detection: pointerWithin for palette drops, closestCenter for canvas reordering
   150→	const collisionDetection: CollisionDetection = (args) => {
   151→		// If dragging from palette (has questionType), use pointerWithin for cross-container drops
   152→		if (args.active.data.current?.questionType) {
   153→			const pointerCollisions = pointerWithin(args);
   154→			if (pointerCollisions.length > 0) {
   155→				return pointerCollisions;
   156→			}
   157→		}
   158→		// For canvas reordering, use closestCenter for better sortable behavior
   159→		return closestCenter(args);
   160→	};
   161→
   162→	const handleDragStart = (event: DragStartEvent) => {
   163→		setDropped(false);
   164→		const { active } = event;
   165→		const data = active.data.current;
   166→
   167→		if (data?.questionType) {
   168→			// Dragging from palette
   169→			setActiveDragItem({
   170→				type: "palette",
   171→				questionType: data.questionType as Question["type"],
   172→			});
   173→		} else {
   174→			// Dragging existing question
   175→			setActiveDragItem({
   176→				type: "question",
   177→				id: active.id as string,
   178→			});
   179→		}
   180→	};
   181→
   182→	const handleDragOver = (event: DragOverEvent) => {
   183→		const { over } = event;
   184→		setOverId(over?.id as string | null);
   185→	};
   186→
   187→	const handleDragEnd = (event: DragEndEvent) => {
   188→		const { active, over } = event;
   189→		setDropped(!!over);
   190→		setActiveDragItem(null);
   191→		setOverId(null);
   192→
   193→		if (!over) return;
   194→
   195→		// Handle cancel drop
   196→		if (over.id === "palette-cancel-zone") {
   197→			return;
   198→		}
   199→
   200→		// Handle palette drop (from question type palette) - use tracked drop index
   201→		if (active.data.current?.questionType) {
   202→			const questionType = active.data.current.questionType as Question["type"];
   203→
   204→			// Calculate insert index based on over.id
   205→			const overIndex = questions.findIndex((q) => q.id === over.id);
   206→			const insertIndex = overIndex === -1 ? questions.length : overIndex;
   207→
   208→			// Optimistic update
   209→			const tempId = `temp-${crypto.randomUUID()}`;
   210→			const mockQuestion = createMockQuestion(questionType);
   211→			const optimisticQuestion = { ...mockQuestion, id: tempId };
   212→
   213→			const optimisticQuestions = [
   214→				...questions
   215→					.slice(0, insertIndex)
   216→					.map((q, i) => ({ ...q, order: i })),
   217→				{ ...optimisticQuestion, order: insertIndex },
   218→				...questions
   219→					.slice(insertIndex)
   220→					.map((q, i) => ({ ...q, order: insertIndex + 1 + i })),
   221→			];
   222→
   223→			setQuestions(optimisticQuestions);
   224→			setSelectedQuestionId(tempId);
   225→
   226→			// Create question and reorder
   227→			client.question
   228→				.create({
   229→					surveyId: survey.id,
   230→					type: questionType,
   231→					title: `New ${questionTypeLabels[questionType] || questionType}`,
   232→					order: insertIndex,
   233→				})
   234→				.then((newQuestion) => {
   235→					// Replace optimistic question with real one
   236→					setQuestions((currentQuestions) => {
   237→						const updatedQuestions = currentQuestions.map((q) =>
   238→							q.id === tempId ? newQuestion : q,
   239→						);
   240→						return updatedQuestions;
   241→					});
   242→
   243→					setSelectedQuestionId((currentId) =>
   244→						currentId === tempId ? newQuestion.id : currentId,
   245→					);
   246→
   247→					queryClient.invalidateQueries({ queryKey: ["question"] });
   248→
   249→					// Reorder all questions on backend to ensure consistency
   250→					const finalQuestions = [
   251→						...questions
   252→							.slice(0, insertIndex)
   253→							.map((q, i) => ({ ...q, order: i })),
   254→						{ ...newQuestion, order: insertIndex },
   255→						...questions
   256→							.slice(insertIndex)
   257→							.map((q, i) => ({ ...q, order: insertIndex + 1 + i })),
   258→					];
   259→
   260→					reorderMutation.mutate({
   261→						questions: finalQuestions.map((q) => ({
   262→							id: q.id,
   263→							order: q.order,
   264→						})),
   265→					});
   266→
   267→					toast.success("Question added");
   268→				})
   269→				.catch((error: Error) => {
   270→					// Revert on error
   271→					setQuestions(questions);
   272→					if (selectedQuestionId === tempId) setSelectedQuestionId(null);
   273→					toast.error(error.message || "Failed to create question");
   274→				});
   275→
   276→			return;
   277→		}
   278→
   279→		// Handle reordering
   280→		if (active.id !== over.id && over.id !== "canvas") {
   281→			const oldIndex = questions.findIndex((q) => q.id === active.id);
   282→			const newIndex = questions.findIndex((q) => q.id === over.id);
   283→
   284→			if (oldIndex !== -1 && newIndex !== -1) {
   285→				const newQuestions = arrayMove(questions, oldIndex, newIndex).map(
   286→					(q, index) => ({
   287→						...q,
   288→						order: index,
   289→					}),
   290→				);
   291→
   292→				setQuestions(newQuestions);
   293→
   294→				reorderMutation.mutate({
   295→					questions: newQuestions.map((q) => ({
   296→						id: q.id,
   297→						order: q.order,
   298→					})),
   299→				});
   300→			}
   301→		}
   302→	};
   303→
   304→	const contextValue: SurveyBuilderContextValue = {
   305→		survey,
   306→		questions,
   307→		selectedQuestionId,
   308→		setSelectedQuestionId,
   309→		activeTab,
   310→		setActiveTab,
   311→		onQuestionsChange: setQuestions,
   312→		paletteOpen,
   313→		setPaletteOpen,
   314→		propertiesOpen,
   315→		setPropertiesOpen,
   316→	};
   317→
   318→	const safeQuestions = questions || [];
   319→
   320→	// Render drag overlay
   321→	const renderDragOverlay = () => {
   322→		if (!activeDragItem) return null;
   323→
   324→		if (activeDragItem.type === "palette") {
   325→			const mockQuestion = createMockQuestion(activeDragItem.questionType);
   326→			return (
   327→				<div className="w-[calc(100vw-3rem)] max-w-2xl">
   328→					<QuestionCardContent
   329→						question={mockQuestion}
   330→						isSelected={false}
   331→						hasLogic={false}
   332→						isOverlay={true}
   333→					/>
   334→				</div>
   335→			);
   336→		}
   337→
   338→		// Dragging existing question
   339→		const activeQuestion = safeQuestions.find(
   340→			(q) => q.id === activeDragItem.id,
   341→		);
   342→		if (activeQuestion) {
   343→			return (
   344→				<div className="w-[calc(100vw-3rem)] max-w-2xl">
   345→					<QuestionCardContent
   346→						question={activeQuestion}
   347→						isSelected={selectedQuestionId === activeQuestion.id}
   348→						hasLogic={false}
   349→						isOverlay={true}
   350→					/>
   351→				</div>
   352→			);
   353→		}
   354→
   355→		return null;
   356→	};
   357→
   358→	return (
   359→		<SurveyBuilderContext.Provider value={contextValue}>
   360→			<DndContext
   361→				sensors={sensors}
   362→				collisionDetection={collisionDetection}
   363→				onDragStart={handleDragStart}
   364→				onDragOver={handleDragOver}
   365→				onDragEnd={handleDragEnd}
   366→			>
   367→				<div className={cn("flex h-full flex-col", className)}>
   368→					<BuilderHeader
   369→						leftActions={
   370→							!isDesktop &&
   371→							activeTab === "build" && (
   372→								<div className="flex items-center gap-1">
   373→									<Button
   374→										variant="ghost"
   375→										size="icon"
   376→										onClick={() => setPaletteOpen(!paletteOpen)}
   377→									>
   378→										<PanelLeftClose className="h-4 w-4" />
   379→									</Button>
   380→								</div>
   381→							)
   382→						}
   383→						rightActions={
   384→							!isDesktop &&
   385→							activeTab === "build" && (
   386→								<div className="flex items-center gap-1">
   387→									<Button
   388→										variant="ghost"
   389→										size="icon"
   390→										onClick={() => setPropertiesOpen(!propertiesOpen)}
   391→									>
   392→										<PanelRightClose className="h-4 w-4" />
   393→									</Button>
   394→								</div>
   395→							)
   396→						}
   397→					/>
   398→					<div className="flex flex-1 overflow-hidden">
   399→						{/* Left Palette - Responsive */}
   400→						{activeTab === "build" && (
   401→							<>
   402→								{/* Desktop: Fixed sidebar */}
   403→								{isDesktop && <QuestionPalette />}
   404→
   405→								{/* Tablet/Mobile: Sheet overlay */}
   406→								{!isDesktop && (
   407→									<Sheet open={paletteOpen} onOpenChange={setPaletteOpen}>
   408→										<SheetContent side="left" className="w-72 p-0">
   409→											<QuestionPalette />
   410→										</SheetContent>
   411→									</Sheet>
   412→								)}
   413→							</>
   414→						)}
   415→
   416→						{/* Canvas */}
   417→						<BuilderCanvas
   418→							questions={questions}
   419→							onQuestionsChange={setQuestions}
   420→							activeDragItem={activeDragItem}
   421→							overId={overId}
   422→							dropped={dropped}
   423→						/>
   424→
   425→						{/* Right Properties Panel - Responsive */}
   426→						{activeTab === "build" && (
   427→							<>
   428→								{/* Desktop: Fixed sidebar */}
   429→								{isDesktop && <PropertiesPanel />}
   430→
   431→								{/* Tablet/Mobile: Sheet overlay */}
   432→								{!isDesktop && (
   433→									<Sheet open={propertiesOpen} onOpenChange={setPropertiesOpen}>
   434→										<SheetContent side="right" className="w-80 p-0">
   435→											<PropertiesPanel />
   436→										</SheetContent>
   437→									</Sheet>
   438→								)}
   439→							</>
   440→						)}
   441→					</div>
   442→				</div>
   443→
   444→				<DragOverlay dropAnimation={dropped ? null : defaultDropAnimation}>
   445→					{renderDragOverlay()}
   446→				</DragOverlay>
   447→			</DndContext>
   448→		</SurveyBuilderContext.Provider>
   449→	);
   450→}
   451→
   452→export { BuilderCanvas } from "./builder-canvas";
   453→// Re-export sub-components for compound pattern
   454→export { BuilderHeader } from "./builder-header";
   455→export { PropertiesPanel } from "./properties-panel";
   456→export { QuestionPalette } from "./question-palette";
   457→

