   308→				question={question}
   309→				isSelected={isSelected}
   310→				hasLogic={hasLogic}
   311→				onSelect={onSelect}
   312→				onDelete={() => deleteMutation.mutate({ id: question.id })}
   313→				isDeleting={deleteMutation.isPending}
   314→				dragHandleProps={{ ...attributes, ...listeners }}
   315→				isDragging={isDragging}
   316→				isOver={isOver}
   317→			/>
   318→		</motion.div>
   319→	);
