   216→				...questions
   217→					.slice(insertIndex)
   218→					.map((q, i) => ({ ...q, order: insertIndex + 1 + i })),
   219→			];
   220→
   221→			setQuestions(optimisticQuestions);
   222→			setSelectedQuestionId(tempId);
   223→
   224→			// Create question and reorder
