   230→					order: insertIndex,
   231→				})
   232→				.then((newQuestion) => {
   233→					// Replace optimistic question with real one
   234→					setQuestions((currentQuestions) => {
   235→						const updatedQuestions = currentQuestions.map((q) =>
   236→							q.id === tempId ? newQuestion : q,
   237→						);
   238→						return updatedQuestions;
   239→					});
   240→
   241→					setSelectedQuestionId((currentId) =>
   242→						currentId === tempId ? newQuestion.id : currentId,
   243→					);
