   247→					// Reorder all questions on backend to ensure consistency
   248→					const finalQuestions = [
   249→						...questions
   250→							.slice(0, insertIndex)
   251→							.map((q, i) => ({ ...q, order: i })),
   252→						{ ...newQuestion, order: insertIndex },
   253→						...questions
   254→							.slice(insertIndex)
   255→							.map((q, i) => ({ ...q, order: insertIndex + 1 + i })),
   256→					];
