   270→					if (selectedQuestionId === tempId) setSelectedQuestionId(null);
   271→					toast.error(error.message || "Failed to create question");
   272→				});
   273→
   274→			return;
   275→		}
   276→
   277→		// Handle reordering
   278→		if (active.id !== over.id && over.id !== "canvas") {
   279→			const oldIndex = questions.findIndex((q) => q.id === active.id);
   280→			const newIndex = questions.findIndex((q) => q.id === over.id);
   281→
   282→			if (oldIndex !== -1 && newIndex !== -1) {
   283→				const newQuestions = arrayMove(questions, oldIndex, newIndex).map(
   284→					(q, index) => {
   285→						// Only create new object if order actually changed
   286→						if (q.order === index) {
   287→							return q; // Preserve reference
   288→						}
   289→						return { ...q, order: index };
   290→					},
   291→				);
   292→
   293→				setQuestions(newQuestions);
   294→
   295→				reorderMutation.mutate({
   296→					questions: newQuestions.map((q) => ({
   297→						id: q.id,
   298→						order: q.order,
   299→					})),
   300→				});
   301→			}
   302→		}
   303→	};
   304→
   305→	const contextValue: SurveyBuilderContextValue = {
   306→		survey,
   307→		questions,
   308→		selectedQuestionId,
   309→		setSelectedQuestionId,
   310→		activeTab,
   311→		setActiveTab,
   312→		onQuestionsChange: setQuestions,
   313→		paletteOpen,
   314→		setPaletteOpen,
   315→		propertiesOpen,
   316→		setPropertiesOpen,
   317→	};
   318→
   319→	const safeQuestions = questions || [];
   320→
   321→	// Render drag overlay
   322→	const renderDragOverlay = () => {
   323→		if (!activeDragItem) return null;
   324→
   325→		if (activeDragItem.type === "palette") {
   326→			const mockQuestion = createMockQuestion(activeDragItem.questionType);
   327→			return (
   328→				<div className="w-[calc(100vw-3rem)] max-w-2xl">
   329→					<QuestionCardContent
   330→						question={mockQuestion}
   331→						isSelected={false}
   332→						hasLogic={false}
   333→						isOverlay={true}
   334→					/>
   335→				</div>
   336→			);
   337→		}
   338→
   339→		// Dragging existing question
   340→		const activeQuestion = safeQuestions.find(
   341→			(q) => q.id === activeDragItem.id,
   342→		);
   343→		if (activeQuestion) {
   344→			return (
   345→				<div className="w-[calc(100vw-3rem)] max-w-2xl">
