   380→									</Button>
   381→								</div>
   382→							)
   383→						}
   384→						rightActions={
   385→							!isDesktop &&
   386→							activeTab === "build" && (
   387→								<div className="flex items-center gap-1">
   388→									<Button
   389→										variant="ghost"
   390→										size="icon"
   391→										onClick={() => setPropertiesOpen(!propertiesOpen)}
   392→									>
   393→										<PanelRightClose className="h-4 w-4" />
   394→									</Button>
   395→								</div>
   396→							)
   397→						}
   398→					/>
   399→					<div className="flex flex-1 overflow-hidden">
   400→						{/* Left Palette - Responsive */}
   401→						{activeTab === "build" && (
   402→							<>
   403→								{/* Desktop: Fixed sidebar */}
   404→								{isDesktop && <QuestionPalette />}
   405→
   406→								{/* Tablet/Mobile: Sheet overlay */}
   407→								{!isDesktop && (
   408→									<Sheet open={paletteOpen} onOpenChange={setPaletteOpen}>
   409→										<SheetContent side="left" className="w-72 p-0">
   410→											<QuestionPalette />
   411→										</SheetContent>
   412→									</Sheet>
   413→								)}
   414→							</>
   415→						)}
   416→
   417→						{/* Canvas */}
   418→						<BuilderCanvas
   419→							questions={questions}
   420→							onQuestionsChange={setQuestions}
   421→							activeDragItem={activeDragItem}
   422→							overId={overId}
   423→							dropped={dropped}
   424→						/>
   425→
   426→						{/* Right Properties Panel - Responsive */}
   427→						{activeTab === "build" && (
   428→							<>
   429→								{/* Desktop: Fixed sidebar */}
   430→								{isDesktop && <PropertiesPanel />}
   431→
   432→								{/* Tablet/Mobile: Sheet overlay */}
   433→								{!isDesktop && (
   434→									<Sheet open={propertiesOpen} onOpenChange={setPropertiesOpen}>
   435→										<SheetContent side="right" className="w-80 p-0">
   436→											<PropertiesPanel />
   437→										</SheetContent>
   438→									</Sheet>
   439→								)}
   440→							</>
   441→						)}
   442→					</div>
   443→				</div>
   444→
   445→				<DragOverlay dropAnimation={dropped ? null : defaultDropAnimation}>
   446→					{renderDragOverlay()}
   447→				</DragOverlay>
   448→			</DndContext>
   449→		</SurveyBuilderContext.Provider>
   450→	);
   451→}
   452→
   453→export { BuilderCanvas } from "./builder-canvas";
   454→// Re-export sub-components for compound pattern
   455→export { BuilderHeader } from "./builder-header";
   456→export { PropertiesPanel } from "./properties-panel";
