    50→	activeDragItem,
    51→	overId,
    52→	dropped,
    53→}: BuilderCanvasProps) {
    54→	const { survey, selectedQuestionId, setSelectedQuestionId, activeTab } =
    55→		useSurveyBuilder();
    56→
    57→	const queryClient = useQueryClient();
