    76→			},
    77→		}),
    78→	);
    79→
    80→	const handleAddQuestion = () => {
    81→		createMutation.mutate({
    82→			surveyId: survey.id,
    83→			type: "text",
    84→			title: "New Question",
    85→			order: safeQuestions.length,
    86→		});
    87→	};
    88→
    89→	if (activeTab === "preview") {
    90→		return (
