    97→								initial={{ opacity: 0, scale: 0.95 }}
    98→								animate={{ opacity: 1, scale: 1 }}
    99→								exit={{ opacity: 0, scale: 0.95 }}
   100→								transition={{ duration: 0.2 }}
   101→							>
   102→								<Card className="border-dashed">
