   107→										</p>
   108→									</CardContent>
   109→								</Card>
   110→							</motion.div>
   111→						) : (
   112→							<div className="space-y-6">
   113→								{safeQuestions.map((question, index) => (
   114→									<motion.div
   115→										key={question.id}
   116→										initial={{ opacity: 0, y: 20 }}
   117→										animate={{ opacity: 1, y: 0 }}
   118→										exit={{ opacity: 0, x: -100 }}
   119→										transition={{ duration: 0.2, delay: index * 0.05 }}
   120→										layout
   121→									>
   122→										<Card>
   123→											<CardContent className="p-6">
   124→												<div className="mb-4">
   125→													<span className="mb-2 block font-bold text-[10px] text-violet-500 uppercase tracking-widest">
