   203→											: -1;
   204→										const dropIndex =
   205→											rawDropIndex === -1 ? safeQuestions.length : rawDropIndex;
   206→
   207→										// Get the question type being dragged
   208→										const isDraggingPalette =
   209→											activeDragItem?.type === "palette";
   210→										const draggedQuestionType = isDraggingPalette
   211→											? activeDragItem.questionType
   212→											: undefined;
   213→
   214→										// Build items array with drop indicator at correct position
   215→										const items: React.ReactNode[] = [];
   216→
   217→										safeQuestions.forEach((question, index) => {
