   245→													</motion.div>,
   246→												);
   247→											}
   248→
   249→											// Add the question card
   250→											const isDragging =
   251→												activeDragItem?.type === "question" &&
   252→												activeDragItem.id === question.id;
   253→											const isOptimistic = question.id.startsWith("temp-");
   254→											const layoutEnabled = !activeDragItem && !dropped;
   255→
   256→											items.push(
   257→												<motion.div
   258→													key={question.id}
   259→													layout={layoutEnabled ? "position" : false}
   260→													initial={
   261→														isOptimistic
   262→															? false
   263→															: { opacity: 0, y: 20, scale: 0.95 }
   264→													}
   265→													animate={
   266→														isOptimistic
   267→															? false
   268→															: { opacity: 1, y: 0, scale: 1 }
   269→													}
   270→													exit={{
   271→														opacity: 0,
   272→														scale: 0.95,
   273→														transition: { duration: 0.15 },
   274→													}}
   275→													transition={{
   276→														type: "spring",
   277→														stiffness: 400,
   278→														damping: 30,
   279→														mass: 0.8,
   280→													}}
   281→												>
   282→													<QuestionCard
   283→														question={question}
   284→														isSelected={selectedQuestionId === question.id}
   285→														onSelect={() => setSelectedQuestionId(question.id)}
   286→														questions={safeQuestions}
   287→														onQuestionsChange={onQuestionsChange}
   288→													/>
   289→												</motion.div>,
   290→											);
   291→										});
   292→
   293→										// Add indicator at end if hovering at last position or over canvas
   294→										if (
   295→											isDraggingPalette &&
   296→											dropIndex >= safeQuestions.length &&
   297→											draggedQuestionType
   298→										) {
   299→											const mockQuestion =
   300→												createMockQuestion(draggedQuestionType);
   301→											items.push(
   302→												<motion.div
   303→													key="drop-indicator-end"
   304→													initial={{ opacity: 0, height: 0 }}
   305→													animate={{ opacity: 1, height: "auto" }}
   306→													exit={
   307→														dropped
   308→															? {
   309→																	opacity: 1,
   310→																	height: "auto",
   311→																	transition: { duration: 0 },
   312→																}
   313→															: { opacity: 0, height: 0 }
   314→													}
   315→												>
   316→													<QuestionCardContent
   317→														question={mockQuestion}
   318→														isPlaceholder
   319→													/>
   320→												</motion.div>,
   321→											);
   322→										}
   323→
   324→										return items;
   325→									})()}
   326→								</SortableContext>
   327→							</LayoutGroup>
   328→
   329→							<motion.div
   330→								initial={{ opacity: 0 }}
   331→								animate={{ opacity: 1 }}
   332→								transition={{ delay: 0.1 }}
   333→							>
   334→								<Button
   335→									variant="outline"
   336→									className="w-full border-dashed"
   337→									onClick={handleAddQuestion}
   338→									disabled={createMutation.isPending}
   339→								>
   340→									<Plus className="mr-2 h-4 w-4" />
   341→									Add Question
   342→								</Button>
   343→							</motion.div>
   344→						</>
   345→					)}
   346→				</AnimatePresence>
   347→			</div>
   348→		</div>
